import{c as d,Q as a,j as o,m as e}from"./chunks/framework.DOi4mjdC.js";const i=JSON.parse('{"title":"DataCopy简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"DataCopy简介","slug":"datacopy简介"}],"relativePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/DataCopy简介.md","filePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/DataCopy简介.md"}'),r={name:"api/SIMD-API/基础API/Memory数据搬运/DataCopy/DataCopy简介.md"};function l(p,t,y,c,m,D){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="datacopy简介" tabindex="-1">DataCopy简介 <a class="header-anchor" href="#datacopy简介" aria-label="Permalink to &quot;DataCopy简介&quot;">​</a></h1><p>DataCopy系列接口提供全面的数据搬运功能，支持多种数据搬运场景，并可在搬运过程中实现随路格式转换和量化激活等操作。该接口支持Local Memory与Global Memory之间的数据搬运，以及Local Memory内部的数据搬运。</p><p>下表展示了DataCopy各项功能的描述和其通路的支持情况。</p><table tabindex="0"><thead><tr><th>功能</th><th>描述</th><th>Local Memory -&gt; Global Memory</th><th>Global Memory -&gt; Local Memory</th><th>Local Memory -&gt; Local Memory</th></tr></thead><tbody><tr><td>基础数据搬运</td><td>提供基础的数据搬运能力，数据在传输过程中保持原始格式和内容不变，支持连续和非连续的数据搬运。</td><td>√</td><td>√</td><td>√</td></tr><tr><td>增强数据搬运</td><td>对数据搬运能力进行增强，相比于基础数据搬运接口，增加了CO1-&gt;CO2通路的随路计算。</td><td>√</td><td>√</td><td>√</td></tr><tr><td>切片数据搬运</td><td>支持数据的切片搬运，提取多维Tensor数据的子集进行搬运。</td><td>√</td><td>√</td><td>×</td></tr><tr><td>随路转换ND2NZ搬运</td><td>支持在数据搬运时进行ND到NZ格式的转换。</td><td>×</td><td>√</td><td>√</td></tr><tr><td>随路转换NZ2ND搬运</td><td>支持在数据搬运时进行NZ到ND格式的转换。</td><td>√</td><td>×</td><td>×</td></tr><tr><td>随路转换DN2NZ搬运</td><td>支持在数据搬运时进行DN到NZ格式的转换。</td><td>×</td><td>√</td><td>×</td></tr><tr><td>随路量化激活搬运</td><td>支持在数据搬运过程中进行量化和Relu激活等操作，同时支持Local Memory到Global Memory通路NZ到ND格式的转换。</td><td>√</td><td>×</td><td>√</td></tr><tr><td>多维数据搬运</td><td>多维数据搬运接口，相比于基础数据搬运接口，可更加自由配置搬入的维度信息以及对应的Stride。</td><td>×</td><td>√</td><td>×</td></tr></tbody></table>',4)])])}const n=d(r,[["render",l]]);export{i as __pageData,n as default};
